// Simple HTML parser - no external dependencies
const html = $input.item.json.data;

// Extract table rows using regex
const rowRegex = /<tr[^>]*>(.*?)<\/tr>/gis;
const cellRegex = /<td[^>]*>(.*?)<\/td>/gis;

const papers = [];
let rowMatch;
let rowIndex = 0;

while ((rowMatch = rowRegex.exec(html)) !== null) {
  rowIndex++;
  if (rowIndex === 1) continue; // Skip header

  const rowHtml = rowMatch[1];
  const cells = [];
  let cellMatch;

  while ((cellMatch = cellRegex.exec(rowHtml)) !== null) {
    // Remove HTML tags
    const cellText = cellMatch[1]
      .replace(/<[^>]*>/g, '')
      .replace(/&nbsp;/g, ' ')
      .trim();
    cells.push(cellText);
  }

  if (cells.length >= 9) {
    // Extract PDF URL
    const urlMatch = rowHtml.match(/href=["'](.*?\.pdf)["']/i);
    let pdfUrl = urlMatch ? urlMatch[1] : '';

    if (pdfUrl && !pdfUrl.startsWith('http')) {
      pdfUrl = 'https://lenr-canr.org/' + pdfUrl.replace(/^\//, '');
    }

    if (cells[5] && pdfUrl) {
      papers.push({
        recnum: cells[0],
        title: cells[5],
        authors: cells[4],
        date_published: cells[2],
        journal: cells[6],
        url: pdfUrl,
        source: 'LENR-CANR',
        date_added: new Date().toISOString().split('T')[0],
        status: 'pending'
      });
    }
  }
}

// Limit to first 10 papers for testing
return papers.slice(0, 10).map(paper => ({ json: paper }));
